add_action( 'woocommerce_order_status_failed', 'perfectpixel_lockdown_count_failure' );
add_action( 'woocommerce_payment_complete', 'perfectpixel_lockdown_reset' );
add_filter( 'woocommerce_available_payment_gateways', 'perfectpixel_lockdown_gateways' );

function perfectpixel_lockdown_count_failure() {
	$count = (int) get_transient( 'perfectpixel_failed_orders' ) + 1;
	set_transient( 'perfectpixel_failed_orders', $count, max( 1, (int) '{{lockdown_window_minutes}}' ) * MINUTE_IN_SECONDS );
	if ( $count >= max( 1, (int) '{{lockdown_failed_count}}' ) && ! get_transient( 'perfectpixel_checkout_lockdown' ) ) {
		$minutes = max( 1, (int) '{{lockdown_minutes}}' );
		set_transient( 'perfectpixel_checkout_lockdown', 1, $minutes * MINUTE_IN_SECONDS );
		delete_transient( 'perfectpixel_failed_orders' );
		wp_mail(
			get_option( 'admin_email' ),
			'[' . wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ) . '] Κλείδωμα πληρωμών μετά από αποτυχημένες παραγγελίες',
			sprintf( "Έγιναν %d αποτυχημένες παραγγελίες σε σύντομο χρόνο. Οι τρόποι πληρωμής %s είναι απενεργοποιημένοι για %d λεπτά.\nΕλέγξτε τις παραγγελίες για πιθανή επίθεση.", $count, '{{lockdown_gateways}}', $minutes )
		);
	}
}

function perfectpixel_lockdown_reset() {
	delete_transient( 'perfectpixel_failed_orders' );
}

function perfectpixel_lockdown_gateways( $gateways ) {
	if ( is_admin() || ! get_transient( 'perfectpixel_checkout_lockdown' ) ) {
		return $gateways;
	}
	foreach ( array_filter( array_map( 'trim', explode( ',', '{{lockdown_gateways}}' ) ) ) as $id ) {
		unset( $gateways[ $id ] );
	}
	return $gateways;
}
